import{_ as a,o as t,c as s,a3 as i}from"./chunks/framework.WFmvnizL.js";const k=JSON.parse('{"title":"国际化与双语文档","description":"参与哪吒监控国际化：Dashboard gettext 模板和编译、前端 i18next 翻译、双语文档路由与元数据对齐及验证。","frontmatter":{"description":"参与哪吒监控国际化：Dashboard gettext 模板和编译、前端 i18next 翻译、双语文档路由与元数据对齐及验证。","outline":"deep"},"headers":[],"relativePath":"developer/i18n.md","filePath":"developer/i18n.md","lastUpdated":1792850916000}'),o={name:"developer/i18n.md"};function d(l,e,n,c,h,r){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="国际化与双语文档" tabindex="-1">国际化与双语文档 <a class="header-anchor" href="#国际化与双语文档" aria-label="Permalink to &quot;国际化与双语文档&quot;">​</a></h1><p>哪吒有三套独立的语言资源：Dashboard Go 文本、用户/管理前端 UI，以及文档站。修改其中一处不会自动翻译其它部分。</p><h2 id="通过-weblate-参与" tabindex="-1">通过 Weblate 参与 <a class="header-anchor" href="#通过-weblate-参与" aria-label="Permalink to &quot;通过 Weblate 参与&quot;">​</a></h2><p>日常翻译优先通过 <a href="https://hosted.weblate.org/engage/nezha/" target="_blank" rel="noreferrer">Nezha Hosted Weblate</a> 提交，避免与自动同步产生重复改动。新增源文本或新语言时，仍需在对应仓库接入资源。</p><h2 id="dashboard-gettext" tabindex="-1">Dashboard：gettext <a class="header-anchor" href="#dashboard-gettext" aria-label="Permalink to &quot;Dashboard：gettext&quot;">​</a></h2><p>资源位于 <code>pkg/i18n/translations/&lt;locale&gt;/LC_MESSAGES/nezha.po</code> 与编译后的 <code>nezha.mo</code>；模板为 <code>pkg/i18n/template.pot</code>。使用已有 Localizer 的 <code>T</code>、<code>Tf</code>、<code>ErrorT</code>、<code>N</code> 等方法，不在处理器里直接拼接待翻译句子。</p><p>在 Dashboard 根目录、Bash 4+ 与 gettext 工具可用时运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script/i18n.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> template</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script/i18n.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zh_CN</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script/i18n.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zh_CN</span></span></code></pre></div><p>顺序为提取源文本、合并 PO、完成翻译、编译 MO。最后两步之间应编辑/审查 PO。只改 PO 不会更新运行时嵌入的 MO，编译后还需重建 Dashboard。新增语种时核对实际资源目录及语言注册，不将某个前端的区域码格式直接搬进后端。</p><p><code>Tf</code>/<code>ErrorT</code> 的格式占位符必须与原文对应；复数词条沿用 <code>N</code> 的现有约定。不要翻译 JSON 字段、API 路径、scope、命令或程序读取的枚举值。</p><h2 id="用户与管理前端-i18next" tabindex="-1">用户与管理前端：i18next <a class="header-anchor" href="#用户与管理前端-i18next" aria-label="Permalink to &quot;用户与管理前端：i18next&quot;">​</a></h2><p>两个前端都在各自 <code>src/locales</code> 下维护 JSON，但语言目录、注册和键不保证相同。用户前端入口为 <code>src/i18n.js</code>，管理前端为 <code>src/lib/i18n.ts</code>。</p><p>新增键时同步基础语言与翻译，保持插值名、复数和嵌套结构。新增语言要导入资源、登记语言代码并检查切换器。不能只新增 JSON 文件就宣称支持。</p><p>翻译验收包括长文本、按钮换行、日期/数字格式、缺失键回退、语言切换后的状态保留。不要为匹配中文宽度写死组件尺寸。主题贡献还需跑<a href="/developer/testing.html">前端检查</a>。</p><h2 id="文档站-成对维护" tabindex="-1">文档站：成对维护 <a class="header-anchor" href="#文档站-成对维护" aria-label="Permalink to &quot;文档站：成对维护&quot;">​</a></h2><p>中文 <code>docs/&lt;section&gt;/&lt;page&gt;.md</code> 对应英文 <code>docs/en_US/&lt;section&gt;/&lt;page&gt;.md</code>。每次功能文档更新同时检查：</p><ul><li>标题、说明、默认值、边界条件和示例语义一致。</li><li>英文内部链接指向 <code>/en_US/</code> 对应页面，锚点在目标语言真实存在。</li><li>导航修改在 <code>docs/.vitepress/config.mts</code> 两个语言区同步。</li><li>页面有准确的 <code>description</code>；共享 SEO 逻辑生成 canonical、hreflang、站点地图和结构化数据。</li><li>对重要入口同步 <code>docs/public/llms.txt</code>，不用隐藏的结构化文本宣传正文没有的能力。</li></ul><p>在文档根目录执行 <code>npm test</code> 和 <code>git diff --check</code>。机器检查验证结构，仍要人工核对权限、默认值和否定句，避免翻译把“不能”变成“可以”。</p>`,18)])])}const g=a(o,[["render",d]]);export{k as __pageData,g as default};
